html:
{% set campus = frappe.get_doc("Campus", doc.campus) if doc.campus else None %}
{% set applicant = frappe.get_doc("Applicant", doc.applicant) if doc.applicant else None %}
{% set snapshot = frappe.get_all("Offer Fee Snapshot", filters={"offer_id": doc.name}, fields=["*"], limit=1) %}
{% set fee_info = snapshot[0] if snapshot else None %}

<style>
    @page {
        size: A4;
        margin: 12mm 15mm;
    }

    .ol-print-wrapper {
        font-family: 'Inter', system-ui, -apple-system, sans-serif;
        color: #1a202c;
        font-size: 10.5pt;
        line-height: 1.5;
        max-width: 100%;
    }

    .ol-header {
        display: flex;
        align-items: center;
        padding-bottom: 8px;
        border-bottom: 2.5px solid #800000;
        margin-bottom: 20px;
    }

    .ol-logo-area {
        flex: 0 0 130px;
        padding: 4px;
        border: 1px solid #333;
        border-radius: 6px 6px 0 0;
        background: #fff;
        margin-right: 20px;
        text-align: center;
        position: relative;
    }

    .ol-logo-area::after {
        content: '';
        position: absolute;
        bottom: -4px;
        left: 0;
        width: 100%;
        height: 4px;
        background: #800000;
    }

    .ol-logo-area img {
        max-width: 110px;
        max-height: 90px;
        object-fit: contain;
    }

    .ol-org-info {
        flex: 1;
    }

    .ol-org-name {
        font-family: 'Times New Roman', serif;
        font-size: 24pt;
        font-weight: 800;
        color: #1a202c;
        margin: 0;
        line-height: 1.1;
        text-transform: uppercase;
    }

    .ol-org-sub {
        font-size: 8.5pt;
        color: #4a5568;
        margin-top: 4px;
        font-weight: 600;
        letter-spacing: 0.01em;
    }

    .ol-contact-row {
        font-size: 7.5pt;
        margin-top: 6px;
        color: #2d3748;
        font-weight: 600;
        border-top: 1px solid #e2e8f0;
        padding-top: 4px;
    }

    .ol-date {
        text-align: right;
        margin-bottom: 20px;
        font-weight: 700;
    }

    .ol-salutation {
        font-weight: 600;
        margin-bottom: 12px;
    }

    .ol-congrats {
        font-weight: 700;
        margin-bottom: 20px;
    }

    .ol-para {
        text-align: justify;
        margin-bottom: 12px;
    }

    .ol-list {
        margin-left: 15px;
        padding-left: 10px;
    }

    .ol-list > li {
        margin-bottom: 15px;
        padding-left: 8px;
    }

    .ol-sub-list {
        list-style-type: lower-alpha;
        margin-top: 8px;
        padding-left: 20px;
    }

    .ol-sub-list li {
        margin-bottom: 4px;
    }

    .ol-fee-box {
        background: #f8fafc;
        border-left: 4px solid #800000;
        padding: 10px 15px;
        margin: 15px 0;
        font-size: 10pt;
    }

    .ol-sig-area {
        margin-top: 50px;
    }

    .ol-sig-placeholder {
        height: 50px;
        font-family: 'Brush Script MT', cursive;
        font-size: 26pt;
        color: #2b6cb0;
        margin: 0;
    }

    .ol-sig-title {
        font-weight: 700;
        margin-top: 0;
    }

    .ol-footer {
        margin-top: 60px;
        border-top: 1px solid #cbd5e0;
        padding-top: 8px;
        font-size: 8pt;
        color: #718096;
        text-align: center;
        font-weight: 500;
    }

    .bold { font-weight: 700; }
    .red-text { color: #800000; }
</style>

<div class="ol-print-wrapper">
    <!-- Header -->
    <div class="ol-header">
        <div class="ol-logo-area">
            {% if campus and campus.logo %}
                <img src="{{ campus.logo }}" alt="Logo">
            {% else %}
                <div style="height: 80px; display:flex; align-items:center; justify-content:center; color:#cbd5e0">LOGO</div>
            {% endif %}
        </div>
        <div class="ol-org-info">
            <h1 class="ol-org-name">{{ campus.campus_name if campus else "NATIONAL UNIVERSITY" }}</h1>
            <div class="ol-org-sub">
                {{ campus.address if campus else "No. 1, University Road" }}
                {% if campus and campus.city %}, {{ campus.city }}{% endif %}
                {% if campus and campus.state %}, {{ campus.state }}{% endif %}
            </div>
            <div class="ol-contact-row">
                Telephone: 080 - 23101000 | Website : www.university.edu.in | Email : registrar@university.edu.in
            </div>
        </div>
    </div>

    <!-- Date -->
    <div class="ol-date">
        Date: <span class="bold">{{ frappe.utils.format_date(doc.issued_on or frappe.utils.today(), "MMMM dd, yyyy") }}</span>
    </div>

    <!-- Greetings -->
    <div class="ol-salutation">
        Dear {{ applicant.candidate_name if applicant else "Candidate" }},
    </div>

    <div class="ol-congrats">
        Congratulations!
    </div>

    <div class="ol-para">
        We are glad to provisionally offer you admission to the <span class="bold">{{ doc.program }}</span> programme at the 
        <span class="bold">{{ campus.campus_name if campus else "University" }}</span>. We look forward to welcoming you to our 
        vibrant academic community.
    </div>

    <div class="ol-para">
        Please log in to the Admission Portal (<span style="color:#2b6cb0; text-decoration: underline;">https://admissions.university.edu.in</span>) 
        to <span class="bold">accept the provisional offer of admission</span> and complete the mandatory steps outlined below:
    </div>

    <ol class="ol-list">
        <li>
            <div class="bold">Confirmation & Fee Payment</div>
            In order to confirm this provisional offer, the following fee amounts are applicable:
            <div class="ol-fee-box">
                {% if fee_info %}
                    <div style="display:flex; justify-content:space-between; margin-bottom:4px;">
                        <span>Total Program Fee:</span>
                        <span class="bold">INR {{ "{:,.2f}".format(fee_info.total_payable + fee_info.scholarship_amount) }}</span>
                    </div>
                    {% if fee_info.scholarship_amount > 0 %}
                    <div style="display:flex; justify-content:space-between; margin-bottom:4px; color:#059669;">
                        <span>Scholarship Benefit:</span>
                        <span class="bold">- INR {{ "{:,.2f}".format(fee_info.scholarship_amount) }}</span>
                    </div>
                    {% endif %}
                    <div style="display:flex; justify-content:space-between; border-top:1px solid #e2e8f0; padding-top:4px; color:#800000; font-size:11pt;">
                        <span>Final Net Payable:</span>
                        <span class="bold">INR {{ "{:,.2f}".format(fee_info.total_payable) }}</span>
                    </div>
                {% else %}
                    <div style="display:flex; justify-content:space-between;">
                        <span>Final Net Payable:</span>
                        <span class="bold">INR {{ "{:,.2f}".format(doc.payable_amount or 0) }}</span>
                    </div>
                {% endif %}
            </div>
            The payment must be completed by <span class="bold">{{ frappe.utils.format_date(doc.payment_deadline, "MMMM dd, yyyy") if doc.payment_deadline else "the specified date" }}</span>.
        </li>

        <li>
            <div class="bold">Document Verification</div>
            This offer is contingent upon the verification of original documents. You are required to produce the following 
            at the time of joining:
            <ul class="ol-sub-list">
                <li>Class 10 and Class 12 Transcripts & Certificates</li>
                <li>Degree/Diploma Certificates (for Post-Graduate programs)</li>
                <li>Caste/Category Certificate (if admission is secured under reserved category)</li>
                <li>EWS/Disability certificates (if applicable)</li>
                <li>Transfer/Migration Certificate from the previous institution</li>
            </ul>
        </li>

        <li>
            <div class="bold">Withdrawal Policy</div>
            Failure to complete the fee payment or document verification within the stipulated timeline will result 
            in the automatic withdrawal of this provisional offer.
        </li>
    </ol>

    <!-- Signature Area -->
    <div class="ol-sig-area">
        <p class="ol-sig-placeholder">Registrar</p>
        <p class="ol-sig-title">Registrar</p>
        <p style="font-size: 9pt; color: #4a5568;">{{ campus.campus_name if campus else "University Administration" }}</p>
    </div>

    <!-- Footer Info -->
    <div class="ol-footer">
        A University established under Academic Excellence Act and recognized by the University Grants Commission.
    </div>
</div>
